<template>
  <div id="containerOuter">
    <div id="container" :style="containerStyle">
      <div
        id="scoreContainer"
        :class="[
          'buttonPressed',
          { 'compact-scoreboard': isCompactScoreboard },
        ]"
        :style="scoreContainerStyle"
      >
        <div id="flag">
          <span
            id="flagIndicator"
            :class="[
              'buttonPressed',
              { 'compact-flag-indicator': isCompactScoreboard },
            ]"
          >
            <span class="segment-display">
              <span
                v-for="(digit, index) in flagDigits"
                :key="`${digit}-${index}`"
                class="segment-digit"
              >
                <span
                  v-for="segment in SEGMENT_NAMES"
                  :key="segment"
                  :class="[
                    'segment',
                    `segment-${segment}`,
                    { active: isSegmentActive(digit, segment) },
                  ]"
                ></span>
              </span>
            </span>
          </span>
        </div>
        <div id="face" class="noSelect">
          <img
            :src="require(`@/assets/emoji/${faceType}.svg`)"
            class="faceImg noSelect buttonNormal"
            @mousedown="(e) => buttonPress(e)"
            @mouseup="
              (e) => {
                buttonRelease(e);
                getFace(0);
                init(this.row, this.col, this.bombPercentage);
              }
            "
            @mouseleave="(e) => buttonRelease(e)"
          />
        </div>
      </div>
      <div id="tableContainer" :style="tableContainerStyle">
        <table
          :key="boardRenderKey"
          id="table"
          class="buttonPressed"
          @contextmenu.prevent
        >
          <tbody id="tableBody" ref="tableBody">
            <tr v-for="r in rowIndex" :key="r">
              <td
                v-for="c in colIndex"
                :key="c"
                class="buttonNormal cellFixed"
                @mousedown="
                  (e) => {
                    buttonPress(e);
                    getFace(1);
                  }
                "
                @mouseup.left="
                  (e) => {
                    if (consumeRevealSuppression(r, c)) {
                      buttonRelease(e);
                      getFace(0);
                      return;
                    }
                    if (e.target.classList.contains('flagged')) {
                      return;
                    }
                    buttonReleaseCell(e);
                    uncoverWrap(r, c); // confirm uncover of cell
                    getFace(0);
                    e.target.classList.add('noClick');
                  }
                "
                @mouseout="
                  (e) => {
                    buttonRelease(e);
                  }
                "
                @contextmenu.prevent="handleCellContextMenu(r, c, $event)"
              ></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
    <div id="optionTab" :style="optionTabStyle">
      <div class="optionPanel">
        <div class="optionSection">
          <div class="optionSectionLabel">Presets</div>
          <div
            class="optionButton buttonNormal"
            @mousedown="(e) => buttonPress(e)"
            @mouseup.left="
              (e) => {
                buttonRelease(e);
                updateInit(1);
              }
            "
          >
            beginner
          </div>
          <div
            class="optionButton buttonNormal"
            @mousedown="(e) => buttonPress(e)"
            @mouseup.left="
              (e) => {
                buttonRelease(e);
                updateInit(2);
              }
            "
          >
            intermediate
          </div>
          <div
            class="optionButton buttonNormal"
            @mousedown="(e) => buttonPress(e)"
            @mouseup.left="
              (e) => {
                buttonRelease(e);
                updateInit(3);
              }
            "
          >
            master
          </div>
        </div>

        <div class="optionDivider"></div>

        <div class="optionSection">
          <div class="optionSectionLabel">Custom</div>
          <div class="optionContent">Rows</div>
          <input
            v-model.lazy="rowInput"
            class="optionInput"
            placeholder=">=7"
          />
          <div class="optionContent">Columns</div>
          <input
            v-model.lazy="colInput"
            class="optionInput"
            placeholder=">=7"
          />
          <div class="optionContent">Bomb %</div>
          <input
            v-model.lazy="bombPercentageInput"
            class="optionInput"
            placeholder="0-1"
          />
          <div
            class="optionButton buttonNormal"
            @mousedown="(e) => buttonPress(e)"
            @mouseup.left="
              (e) => {
                buttonRelease(e);
                updateInit();
              }
            "
          >
            apply
          </div>
        </div>
      </div>
    </div>
    <div
      id="optionShow"
      :style="optionShowStyle"
      @mouseup.left="toggleOption()"
    >
      <div>setup</div>
    </div>
  </div>
</template>

<script>
import { GameState, MinesweeperBoard } from "@/utils/minesweeperEngine.mjs";

const DEFAULT_BOARD = {
  row: 16,
  col: 16,
  bombPercentage: 0.15,
};

const BOARD_PRESETS = {
  beginner: {
    row: 8,
    col: 8,
    bombPercentage: 0.15,
  },
  intermediate: {
    row: 16,
    col: 16,
    bombPercentage: 0.15,
  },
  master: {
    row: 32,
    col: 32,
    bombPercentage: 0.15,
  },
};

const SEGMENT_NAMES = ["a", "b", "c", "d", "e", "f", "g"];
const DIGIT_SEGMENTS = {
  0: ["a", "b", "c", "d", "e", "f"],
  1: ["b", "c"],
  2: ["a", "b", "d", "e", "g"],
  3: ["a", "b", "c", "d", "g"],
  4: ["b", "c", "f", "g"],
  5: ["a", "c", "d", "f", "g"],
  6: ["a", "c", "d", "e", "f", "g"],
  7: ["a", "b", "c"],
  8: ["a", "b", "c", "d", "e", "f", "g"],
  9: ["a", "b", "c", "d", "f", "g"],
};

function createIndexArray(size) {
  return Array.from(Array(size).keys());
}

function getBoardDimensions(row, col) {
  const tableWidth = 25 * col;
  const tableHeight = 25 * row;
  const containerWidth = tableWidth + 40;
  const containerHeight = tableHeight + 100;

  return {
    containerWidth,
    containerHeight,
    scoreWidth: Math.min(containerWidth - 40, 400),
    tableHeight,
    tableWidth,
  };
}

function formatFlagCount(flagCount) {
  return `000${flagCount}`.slice(-4);
}

function createBoard(row, col, bombPercentage) {
  return new MinesweeperBoard(row, col, bombPercentage);
}
export default {
  data() {
    return {
      SEGMENT_NAMES,
      row: DEFAULT_BOARD.row,
      col: DEFAULT_BOARD.col,
      bombPercentage: DEFAULT_BOARD.bombPercentage,
      board: createBoard(
        DEFAULT_BOARD.row,
        DEFAULT_BOARD.col,
        DEFAULT_BOARD.bombPercentage,
      ),
      faceType: "grin0",
      rowInput: null,
      colInput: null,
      bombPercentageInput: null,
      flagStr: formatFlagCount(
        Math.floor(
          DEFAULT_BOARD.row * DEFAULT_BOARD.col * DEFAULT_BOARD.bombPercentage,
        ),
      ),
      optionShown: false,
      suppressedRevealCell: null,
      suppressedRevealResetId: null,
    };
  },
  computed: {
    rowIndex() {
      return createIndexArray(this.row);
    },
    colIndex() {
      return createIndexArray(this.col);
    },
    containerOuterHeight() {
      return `${this.boardDimensions.containerHeight + 70}px`;
    },
    boardDimensions() {
      return getBoardDimensions(this.row, this.col);
    },
    boardRenderKey() {
      return `${this.row}-${this.col}`;
    },
    isCompactScoreboard() {
      return this.boardDimensions.scoreWidth <= 220;
    },
    flagDigits() {
      return String(this.flagStr)
        .padStart(4, "0")
        .slice(-4)
        .split("")
        .map((digit) => Number.parseInt(digit, 10) || 0);
    },
    containerStyle() {
      return {
        width: `${this.boardDimensions.containerWidth}px`,
        height: `${this.boardDimensions.containerHeight}px`,
      };
    },
    scoreContainerStyle() {
      return {
        width: `${this.boardDimensions.scoreWidth}px`,
      };
    },
    tableContainerStyle() {
      return {
        width: `${this.boardDimensions.tableWidth}px`,
        height: `${this.boardDimensions.tableHeight}px`,
      };
    },
    optionShowStyle() {
      return {
        marginLeft: this.optionShown ? "136px" : "0",
      };
    },
    optionTabStyle() {
      return {
        visibility: this.optionShown ? "visible" : "hidden",
      };
    },
  },
  mounted() {
    document.title = "Weili: Minesweeper";
    this.handleViewportChange();
    window.addEventListener("resize", this.handleViewportChange);
  },
  beforeUnmount() {
    window.removeEventListener("resize", this.handleViewportChange);
    if (this.suppressedRevealResetId) {
      window.clearTimeout(this.suppressedRevealResetId);
    }
  },
  methods: {
    getTableBody() {
      return this.$refs.tableBody;
    },
    getCellElement(row, col) {
      return this.getTableBody().rows[row].cells[col];
    },
    isSegmentActive(digit, segment) {
      return DIGIT_SEGMENTS[digit]?.includes(segment);
    },
    consumeRevealSuppression(row, col) {
      const cellKey = `${row}-${col}`;

      if (this.suppressedRevealCell !== cellKey) {
        return false;
      }

      this.suppressedRevealCell = null;
      return true;
    },
    scheduleRevealSuppressionClear() {
      if (this.suppressedRevealResetId) {
        window.clearTimeout(this.suppressedRevealResetId);
      }

      this.suppressedRevealResetId = window.setTimeout(() => {
        this.suppressedRevealCell = null;
        this.suppressedRevealResetId = null;
      }, 0);
    },
    handleViewportChange() {
      this.optionShown = window.innerWidth > 768;
    },
    lockBoard() {
      this.getTableBody().classList.add("noClick");
    },
    unlockBoard() {
      this.getTableBody().classList.remove("noClick");
    },
    renderBombs(explodedCell) {
      this.lockBoard();

      this.board.getBombCells().forEach(({ row, col }) => {
        const element = this.getCellElement(row, col);
        const isExplodedCell =
          explodedCell.row === row && explodedCell.col === col;

        if (element.classList.contains("flagged")) {
          element.classList.remove("flagged", "buttonNormal", "buttonPressed");
          element.classList.add("boom2", "uncovered", "noSelect", "noClick");
          return;
        }

        element.classList.remove("buttonNormal", "buttonPressed");
        element.classList.add("boom", "uncovered", "noSelect", "noClick");

        if (isExplodedCell) {
          element.classList.add("boomRed");
        }
      });
    },
    renderRevealedCells(revealedCells) {
      revealedCells.forEach(({ row, col, bombNum }) => {
        const element = this.getCellElement(row, col);
        element.classList.remove("flagged", "buttonNormal", "buttonPressed");
        element.classList.add(
          `bomb${bombNum}`,
          "uncovered",
          "noSelect",
          "noClick",
        );
      });
    },
    buttonPress(event) {
      event.target.classList.add("buttonPressed");
    },
    buttonReleaseCell(event) {
      event.target.classList.remove("buttonPressed");
      event.target.classList.add("noSelect", "noClick");
    },
    buttonRelease(event) {
      event.target.classList.remove("buttonPressed");
    },
    clearStyle() {
      const body = this.getTableBody();
      const rowNum = body.rows.length;
      if (rowNum == 0) {
        return;
      }
      const colNum = body.rows[0].cells.length;
      for (let i = 0; i < rowNum; i++) {
        for (let j = 0; j < colNum; j++) {
          const element = body.rows[i].cells[j];
          element.classList.remove(
            "boom",
            "uncovered",
            "boomRed",
            "flagged",
            "bomb0",
            "bomb1",
            "bomb2",
            "bomb3",
            "bomb4",
            "bomb5",
            "bomb6",
            "bomb7",
            "bomb8",
            "noClick",
            "boom2",
            "noSelect",
            "buttonPressed",
          );
          element.classList.add("bomb0");
          element.classList.add("buttonNormal");
        }
      }
      this.unlockBoard();
    },
    getFace(type) {
      const state = this.board.state;
      const rand = Math.floor(Math.random() * 2);
      if (state == GameState.Dead) {
        this.faceType = "dead" + rand;
        return;
      }
      if (state == GameState.Won) {
        this.faceType = "win";
        this.lockBoard();
        this.$confetti.start();
        return;
      }
      if (type == 1) {
        this.faceType = "oops" + rand;
        return;
      }
      this.faceType = "grin" + rand;
    },
    init(row, col, bombPercentage) {
      this.$confetti.stop();
      this.board = createBoard(
        Number.parseInt(row, 10),
        Number.parseInt(col, 10),
        bombPercentage,
      );
      this.clearStyle();
      this.updateFlagCnt();
      this.getFace(0);
    },
    toggleFlag(row, col, e) {
      const result = this.board.toggleFlag(row, col);

      if (result.reason === "no-flags-remaining") {
        alert("no flags remain");
        return;
      }

      if (result.reason === "flagged") {
        e.target.classList.add(`flagged`);
      } else if (result.reason === "unflagged") {
        e.target.classList.remove(`flagged`);
      }
      this.updateFlagCnt();
    },
    handleCellContextMenu(row, col, event) {
      this.suppressedRevealCell = `${row}-${col}`;
      this.scheduleRevealSuppressionClear();
      this.buttonRelease(event);
      this.getFace(0);
      this.toggleFlag(row, col, event);
    },
    toggleOption() {
      this.optionShown = !this.optionShown;
    },
    uncoverWrap(r, c) {
      const result = this.board.reveal(r, c);

      if (!result.changed) {
        return;
      }

      if (result.reason === "bomb") {
        this.renderBombs(result.explodedCell);
        this.getFace(0);
        return;
      }

      this.renderRevealedCells(result.revealed);

      if (result.won) {
        this.getFace(0);
      }
    },
    updateFlagCnt() {
      this.flagStr = formatFlagCount(this.board.flagCnt);
    },
    async updateInit(type = 0) {
      let r, c, bp;
      if (type == 0) {
        r = Number.parseInt(this.rowInput, 10);
        c = Number.parseInt(this.colInput, 10);
        bp = Number.parseFloat(this.bombPercentageInput);
      } else if (type == 1) {
        ({ row: r, col: c, bombPercentage: bp } = BOARD_PRESETS.beginner);
      } else if (type == 2) {
        ({ row: r, col: c, bombPercentage: bp } = BOARD_PRESETS.intermediate);
      } else if (type == 3) {
        ({ row: r, col: c, bombPercentage: bp } = BOARD_PRESETS.master);
      }
      if (isNaN(r) || isNaN(c) || isNaN(bp) || r < 7 || c < 7) {
        alert("Please check your inputs, #row and #col must >= 7.");
        return;
      } else if (bp < 0 || bp > 1) {
        alert("%Bombs: enter a number in range [0, 1].");
        return;
      }
      this.clearStyle();
      this.row = r;
      this.col = c;
      this.bombPercentage = bp;
      await this.$nextTick();
      this.getFace(0);
      this.init(r, c, bp);
    },
  },
};
</script>

